< +        cres *= 1.0 - 0.6 * uLG4.y * h21(vec2(id + 0.5, sic + 29.0));
< +        cres = min(1.0, cres * (1.0 + uLG6.z));
< +        if (uLG6.w > 0.0) {
< +          // a tiny four-point star on some crescents' middles (the painted water's sparkle); sv = pixels from the middle
< +          float stp = step(0.8, h21(vec2(id + 0.75, sic + 31.0))) * onc;

